import mujoco, numpy as np
from harness import scene, spec, episodes
m,d=episodes.build_episode_scene(35,with_arm=True)
print('model', m.nq,m.nu)
for n in ['arm_link0','arm_link7','arm_attachment','arm_magnet','arm_wrist']:
    try:
      b=m.body(n); print(n, b.id, d.xpos[b.id], d.xmat[b.id].reshape(3,3))
    except Exception as e: print(e)
for i in range(7):
    a=m.actuator(f'arm_actuator{i+1}'); print(i+1,a.ctrlrange, m.jnt_range[m.joint(f'arm_joint{i+1}').id])
scene.set_arm(m,d,spec.ARM_HOME)
print('home')
for n in ['arm_attachment','arm_magnet']:
    b=m.body(n); print(n,d.xpos[b.id], d.xmat[b.id].reshape(3,3))
print('grip', d.site('arm_grip').xpos, d.site('arm_grip').xmat.reshape(3,3))
print('parts', scene.n_parts(m))
for i in range(scene.n_parts(m)):
    p,q=scene.part_pose(d,i); print(i,spec.PART_LENGTH_SCALES[__import__('harness.parts',fromlist=['part_class']).part_class(m,i)],p,q)
